    brewer VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Drinker (
    name VARCHAR NOT NULL,
    address VARCHAR NOT NULL,
    PRIMARY KEY (name)
);

CREATE TABLE Frequents (
    drinker VARCHAR NOT NULL,
    bar VARCHAR NOT NULL,
    times_a_week SMALLINT NOT NULL,
    PRIMARY KEY (drinker, bar),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (bar) REFERENCES Bar(name)
);

CREATE TABLE Serves (
    bar VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    price DECIMAL(5,2) NOT NULL,
    PRIMARY KEY (bar, beer),
    FOREIGN KEY (bar) REFERENCES Bar(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

CREATE TABLE Likes (
    drinker VARCHAR NOT NULL,
    beer VARCHAR NOT NULL,
    PRIMARY KEY (drinker, beer),
    FOREIGN KEY (drinker) REFERENCES Drinker(name),
    FOREIGN KEY (beer) REFERENCES Beer(name)
);

counterexample:
INSERT INTO Bar (name, address) VALUES ('BarX', '123 Main St'), ('BarY', '456 Side St');
INSERT INTO Drinker (name, address) VALUES ('Alice', '101 A St'), ('Bob', '202 B St');
INSERT INTO Beer (name, brewer) VALUES ('Beer1', 'BrewCo'), ('Beer2', 'BrewCo');
INSERT INTO Frequents (drinker, bar, times_a_week) VALUES ('Alice', 'BarX', 3), ('Alice', 'BarY', 5), ('Bob', 'BarX', 4);
INSERT INTO Serves (bar, beer, price) VALUES ('BarX', 'Beer1', 5.00), ('BarX', 'Beer2', 4.50), ('BarY', 'Beer1', 6.00), ('BarY', 'Beer2', 5.50);

